final class OvenBoard implements AutoCloseable {
    private final AtomicReference<Reading> latest = new AtomicReference<>();
    private final Disposable boardConnection;
    final Flux<Reading> live;

    OvenBoard(Flux<Reading> thermometer) {
        // for the hall board: connect now, retry after a second, keep the latest in a field
        this.boardConnection = thermometer
            .retryWhen(Retry.fixedDelay(Long.MAX_VALUE, Duration.ofSeconds(1))
                .filter(e -> e instanceof IOException))
            .subscribe(latest::set);
        // for the screens: connect with the first, disconnect 5 s after the last
        this.live = thermometer.replay(1).refCount(1, Duration.ofSeconds(5));
    }

    Reading current() { return latest.get(); }

    @Override public void close() { boardConnection.dispose(); }
}

