class OvenBoard(thermometer: Flow<Reading>, scope: CoroutineScope) {
    // for the hall board: .value is not a subscription, so start now
    val board: StateFlow<Reading?> = thermometer
        .retry { e -> (e is IOException).also { if (it) delay(1_000) } }
        .stateIn(scope, SharingStarted.Eagerly, null)

    // for the screens: survive a 5 s flicker, then stop and forget the old reading
    val live: StateFlow<Reading?> = thermometer
        .stateIn(scope, SharingStarted.WhileSubscribed(5_000, replayExpirationMillis = 0), null)

    fun current(): Reading? = board.value
}
