class KitchenBell {
    private val bell = MutableSharedFlow<Announcement>(extraBufferCapacity = 64)   // SUSPEND, the default
    val announcements: SharedFlow<Announcement> = bell.asSharedFlow()

    // false only when some subscriber already has 64 announcements it hasn't taken;
    // the caller must not treat the announcement as delivered then. With no subscriber
    // it is always true, and the announcement goes nowhere.
    fun ring(a: Announcement): Boolean = bell.tryEmit(a)
}

// the diary keeper copies values off the shared buffer at once, into a channel of its own
suspend fun keepDiary(bell: KitchenBell, diary: Diary) =
    bell.announcements.buffer(1_000).collect { diary.write(it) }

