// Java equivalent: a buffered multicast sink, and a buffer of its own on the diary side
class KitchenBell {
    private final Sinks.Many<Announcement> bell = Sinks.many().multicast().onBackpressureBuffer(64, false);

    Flux<Announcement> announcements() { return bell.asFlux(); }

    // false when the buffer is full (FAIL_OVERFLOW); synchronized because a Reactor sink
    // refuses concurrent emits with FAIL_NON_SERIALIZED
    synchronized boolean ring(Announcement a) { return bell.tryEmitNext(a).isSuccess(); }
}

Disposable keepDiary(KitchenBell bell, Diary diary) {
    return bell.announcements()
        .onBackpressureBuffer(1_000)
        .publishOn(Schedulers.boundedElastic())
        .subscribe(diary::write);
}
